import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	a := make([]int, n)
	ones := 0
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
		if a[i] == 1 {
			ones++
		}
	}

	// Edge case: if all are 1s, flipping any segment must reduce count by at least 1
	if ones == n {
		fmt.Println(n - 1)
		return
	}

	// Transform array: 0 -> +1, 1 -> -1
