	bestGain := -1 << 30
	current := 0
	for i := 0; i < n; i++ {
		val := 1
		if a[i] == 1 {
			val = -1
		}
		if current+val < val {
			current = val
		} else {
			current += val
		}
		if current > bestGain {
			bestGain = current
		}
	}

	fmt.Println(ones + bestGain)
}
